.venv/bin/python -c "import numpy as np; from itertools import combinations; np.random.seed(0); X=np.random.randn(80,50); y=(np.random.rand(80)>0.5).astype(int)*2-1; max_acc=0; folds=np.array_split(np.arange(80), 5); 
for i, j in combinations(range(50), 2):
    X_sub=np.hstack([np.ones((80,1)), X[:, [i, j]]]); accs=[]
    for k in range(5):
        val=folds[k]; tr=np.concatenate([folds[f] for f in range(5) if f!=k])
        w=np.linalg.lstsq(X_sub[tr], y[tr], rcond=None)[0]
        accs.append(np.mean(np.sign(X_sub[val] @ w) == y[val]))
    if np.mean(accs)>max_acc: max_acc=np.mean(accs)
print(max_acc)"

